/** daysSinceRoast: whole days between the ISO roast date `roastedOn` (e.g. "2026-10-12") and `today`. */
export function daysSinceRoast(roastedOn: string, today: Date): number {
  const roast = Date.parse(`${roastedOn}T00:00:00Z`);
  const day = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate());
  return Math.round((day - roast) / 86_400_000);
}

/** isFresh: true while the roast is 14 days old or younger (inclusive). */
export function isFresh(roastedOn: string, today: Date): boolean {
  const days = daysSinceRoast(roastedOn, today);
  return days >= 0 && days <= 14;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { daysSinceRoast, isFresh } from "../src/freshness.ts";

const today = new Date("2026-10-20T15:30:00Z");

test("day 0: roast date is today", () => {
  assert.equal(daysSinceRoast("2026-10-20", today), 0);
  assert.equal(isFresh("2026-10-20", today), true);
});

test("day 14: still fresh", () => {
  assert.equal(daysSinceRoast("2026-10-06", today), 14);
  assert.equal(isFresh("2026-10-06", today), true);
});

test("day 15: no longer fresh", () => {
  assert.equal(daysSinceRoast("2026-10-05", today), 15);
  assert.equal(isFresh("2026-10-05", today), false);
});
